INSERT INTO spot_photos
(
	spot_id,
	display_order,
	photo_url
) VALUES (
	#{spotId},
	(
		SELECT MAX(COALESCE(display_order, 0)) FROM spot_photos
		WHERE spot_id = #{spotId}
	) + 1,
	#{photoUrl}
)

mapper.select:
SELECT EXIST (
	SELECT 1
	FROM spot_photos
	WHERE photo_url = #{photoUrl}
)

